import pandas as pd

def gold_cards_issued_before_1998(card):
    condition = (card['type'] == 'Gold') & (card['issued'].dt.year < 1998)
    return round(100 * condition.mean(), 2)
```

```python
def get_client_region(client_df, district_df, client_id):
    return district_df.loc[district_df['district_id'] == client_df.loc[client_id, 'district_id'], ['A2', 'A3']].values.flatten()
```

```python
import pandas as pd

def who_placed_order_32423(order, account):
    result = order[order['order_id'] == 32423]
    if not result.empty:
        return result.merge(account, how='left', left_on='account_id', right_on='account_id')['client_id'].iloc[0]
    else:
        return None
```

